-- Explicit read policy batch; private/global-response caches and product assets remain gated.
CREATE FUNCTION tj_private.has_active_mapped_org() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM tj.organization_members m JOIN tj.organizations o ON o.id=m.organization_id WHERE m.user_id=(SELECT tj_private.current_source_user_id()) AND m.status='active' AND o.status='active' AND o.deleted_at IS NULL);
$$;
CREATE FUNCTION tj_private.is_source_self(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT p_user IS NOT NULL AND p_user=(SELECT tj_private.current_source_user_id()) AND tj_private.has_active_mapped_org();
$$;
CREATE FUNCTION tj_private.can_read_runtime_org(p_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT tj.is_org_member(p_org) AND EXISTS(SELECT 1 FROM tj.organizations o WHERE o.id=p_org AND o.status='active' AND o.deleted_at IS NULL);
$$;
CREATE FUNCTION tj_private.can_read_source_profile(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT tj_private.is_source_self(p_user) OR EXISTS(SELECT 1 FROM tj.organization_members m WHERE m.user_id=p_user AND m.status='active' AND tj_private.can_read_runtime_org(m.organization_id) AND tj.is_org_admin(m.organization_id));
$$;
REVOKE ALL ON FUNCTION tj_private.has_active_mapped_org() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION tj_private.has_active_mapped_org() TO authenticated;
REVOKE ALL ON FUNCTION tj_private.is_source_self(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION tj_private.is_source_self(uuid) TO authenticated;
REVOKE ALL ON FUNCTION tj_private.can_read_runtime_org(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION tj_private.can_read_runtime_org(uuid) TO authenticated;
REVOKE ALL ON FUNCTION tj_private.can_read_source_profile(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION tj_private.can_read_source_profile(uuid) TO authenticated;
