CREATE POLICY consolidation_progress_insert ON tj.academy_progress FOR INSERT TO authenticated WITH CHECK(tj_private.is_source_self(user_id) AND (completed_at IS NULL OR completed_at<=now()+interval '5 minutes') AND EXISTS(SELECT 1 FROM tj.academy_chapters c WHERE c.id=chapter_id));
CREATE POLICY consolidation_progress_update ON tj.academy_progress FOR UPDATE TO authenticated USING(tj_private.is_source_self(user_id)) WITH CHECK(tj_private.is_source_self(user_id) AND (completed_at IS NULL OR completed_at<=now()+interval '5 minutes') AND EXISTS(SELECT 1 FROM tj.academy_chapters c WHERE c.id=chapter_id));
GRANT INSERT(user_id,chapter_id,completed_at),UPDATE(user_id,chapter_id,completed_at) ON tj.academy_progress TO authenticated;
CREATE POLICY consolidation_notification_read_receipt ON tj.academy_notifications FOR UPDATE TO authenticated USING(tj_private.is_source_self(user_id) AND (organization_id IS NULL OR tj_private.can_read_runtime_org(organization_id))) WITH CHECK(tj_private.is_source_self(user_id) AND (organization_id IS NULL OR tj_private.can_read_runtime_org(organization_id)));
GRANT UPDATE(read) ON tj.academy_notifications TO authenticated;
